import { fileURLToPath } from 'node:url';

/** Name of the per-run sheet inside the built-in template (cloned once per test run). */
export const DEFAULT_TEMPLATE_RUN_SHEET = 'RUN';

/**
 * Absolute path of the built-in report template shipped with this package
 * (`assets/default-report.xlsx`, generated by `scripts/build-default-template.ts`).
 */
export function defaultTemplatePath(): string {
  return fileURLToPath(new URL('../assets/default-report.xlsx', import.meta.url));
}
